('jq-0323-1','math','初中',11,'jkp-0323','single_choice',0.65,'直接开平方解 x² = 16，x = ？','[{"key": "A", "text": "±4"}, {"key": "B", "text": "4"}, {"key": "C", "text": "-4"}, {"key": "D", "text": "16"}]','A','x=±√16=±4','template-j','approved','通用');
