('jq-0324-1','math','初中',11,'jkp-0324','single_choice',0.75,'配方法：x² + 6x + 9 = 0，配方成 (x + 3)² = ？','[{"key": "A", "text": "0"}, {"key": "B", "text": "18"}, {"key": "C", "text": "6"}, {"key": "D", "text": "3"}]','A','(x+3)²=3²-9=0','template-j','approved','通用');
